// ===========================================================================
//  CẤU HÌNH - watchlist kèm NGÀNH (để Claude áp ngưỡng định giá đúng ngành)
// ===========================================================================
const WATCHLIST = [
  { t: 'BID', s: 'Ngân hàng' }, { t: 'VCB', s: 'Ngân hàng' }, { t: 'MBB', s: 'Ngân hàng' }, { t: 'STB', s: 'Ngân hàng' },
  { t: 'BCM', s: 'BĐS Khu công nghiệp' },
  { t: 'FPT', s: 'Công nghệ' },
  { t: 'VNM', s: 'Hàng tiêu dùng' }, { t: 'MWG', s: 'Bán lẻ' },
  { t: 'HPG', s: 'Thép (chu kỳ)' }, { t: 'DGC', s: 'Hoá chất' },
  { t: 'SSI', s: 'Chứng khoán' }, { t: 'VND', s: 'Chứng khoán' },
];
const FOCUS = ['BID', 'BCM', 'FPT']; // mã anh đang cân nhắc - Claude đọc kỹ
// ===========================================================================

// Các chỉ số muốn lấy - thử nhiều tên mã (code) khả dĩ cho mỗi chỉ số.
// pct:true = nếu giá trị < 1 thì coi là tỷ lệ, nhân 100 thành %.
const WANT = [
  { label: 'P/E',          codes: ['PRICE_TO_EARNINGS'], pct: false },
  { label: 'P/B',          codes: ['PRICE_TO_BOOK'], pct: false },
  { label: 'ROE',          codes: ['ROE', 'RETURN_ON_EQUITY'], pct: true },
  { label: 'ROA',          codes: ['ROA', 'RETURN_ON_ASSET', 'RETURN_ON_ASSETS'], pct: true },
  { label: 'Nợ/VCSH',      codes: ['DEBT_EQUITY', 'DEBT_TO_EQUITY', 'LIABILITIES_TO_EQUITY', 'DEBT_ON_EQUITY'], pct: false },
  { label: 'Biên LN ròng', codes: ['NET_PROFIT_MARGIN', 'NET_MARGIN', 'PROFIT_MARGIN'], pct: true },
  { label: 'Cổ tức/giá',   codes: ['DIVIDEND_YIELD'], pct: true },
  { label: 'EPS',          codes: ['EPS', 'BASIC_EPS'], pct: false },
  { label: 'Vốn hoá',      codes: ['MARKET_CAP'], pct: false },
];

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const allCodes = new Set();
const rows = [];
const debug = [];

for (const { t, s } of WATCHLIST) {
  try {
    // VNDirect finfo BẮT BUỘC có filter -> nhồi danh sách rộng các code khả dĩ;
    // code đúng thì trả về, code sai bị bỏ qua (không lỗi). Debug in code thực có.
    const RATIO_FILTER = 'PRICE_TO_EARNINGS,PRICE_TO_BOOK,ROE,RETURN_ON_EQUITY,ROA,RETURN_ON_ASSET,RETURN_ON_ASSETS,DEBT_TO_EQUITY,DEBT_EQUITY,LIABILITIES_TO_EQUITY,NET_PROFIT_MARGIN,NET_MARGIN,PROFIT_MARGIN,DIVIDEND_YIELD,EPS,BASIC_EPS,MARKET_CAP,BVPS';
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api-finfo.vndirect.com.vn/v4/ratios/latest?order=reportDate&where=code:' + t + '&filter=ratioCode:' + RATIO_FILTER + '&fields=ratioCode,value,reportDate',
      headers, json: true, timeout: 15000,
    });
    const data = (res && res.data) || [];
    if (!data.length) { debug.push(t + ': không có chỉ số'); continue; }

    const map = {};
    for (const d of data) {
      allCodes.add(d.ratioCode);
      const prev = map[d.ratioCode];
      if (!prev || (d.reportDate || '') > (prev.date || '')) map[d.ratioCode] = { value: d.value, date: d.reportDate };
    }

    const metrics = {};
    for (const w of WANT) {
      let v = null;
      for (const code of w.codes) { if (map[code] && map[code].value != null) { v = map[code].value; break; } }
      if (v != null && w.pct && Math.abs(v) < 1) v = v * 100;
      metrics[w.label] = v;
    }
    rows.push({ t, s, metrics });
    const pe = metrics['P/E'];
    debug.push(t + ': OK (' + data.length + ' chỉ số, P/E ' + (pe != null ? Number(pe).toFixed(1) : 'n/a') + ')');
  } catch (e) {
    debug.push(t + ': ❌ ' + (e.message || String(e)));
  }
}

// In toàn bộ ratioCode lấy được -> dùng để tinh chỉnh tên chỉ số lần sau
debug.push('CÁC ratioCode CÓ SẴN: ' + [...allCodes].sort().join(', '));

const fmt = (v) => (v == null ? 'n/a' : (Math.abs(v) >= 1000 ? Math.round(v).toLocaleString('vi-VN') : Number(v).toFixed(2)));
let table = '';
for (const r of rows) {
  const m = r.metrics;
  table += (FOCUS.includes(r.t) ? '⭐ ' : '') + r.t + ' (' + r.s + '): '
    + 'P/E ' + fmt(m['P/E']) + ' | P/B ' + fmt(m['P/B'])
    + ' | ROE ' + fmt(m['ROE']) + '% | ROA ' + fmt(m['ROA']) + '%'
    + ' | Nợ/VCSH ' + fmt(m['Nợ/VCSH'])
    + ' | Biên LN ' + fmt(m['Biên LN ròng']) + '%'
    + ' | Cổ tức ' + fmt(m['Cổ tức/giá']) + '%\n';
}

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: 'numeric', month: 'numeric', year: 'numeric' });

const system = 'Bạn là chuyên viên phân tích ĐỊNH GIÁ cổ phiếu Việt Nam, theo trường phái biên an toàn (Graham/Buffett). '
  + 'Dựa vào chỉ số cơ bản mới nhất của từng mã + KIẾN THỨC của bạn về ngưỡng hợp lý THEO NGÀNH, đánh giá mỗi mã RẺ / HỢP LÝ / ĐẮT.\n\n'
  + 'Bối cảnh ngưỡng tham khảo theo ngành VN: Ngân hàng P/E thường thấp (~6-12), P/B 1-2; Công nghệ/Bán lẻ P/E cao hơn (15-25) nếu tăng trưởng tốt; Thép & Hoá chất có tính CHU KỲ (P/E thấp lúc đỉnh lợi nhuận có thể là bẫy); Chứng khoán biến động theo thị trường.\n\n'
  + 'Nguyên tắc bắt buộc:\n'
  + '- Mỗi mã: nêu P/E, P/B; so với ngưỡng hợp lý của CHÍNH NGÀNH đó; đánh giá CHẤT LƯỢNG qua ROE (cao = tốt) và nợ; kết luận RẺ / HỢP LÝ / ĐẮT + 1 câu lý do.\n'
  + '- Đọc kỹ 3 mã ⭐ (BID, BCM, FPT) - người dùng đang cân nhắc mua.\n'
  + '- CẢNH BÁO BẪY: P/E thấp có thể là "bẫy giá trị" (doanh nghiệp đang xấu đi hoặc đỉnh chu kỳ); ROE cao kèm nợ lớn là rủi ro. ĐỪNG kết luận chỉ từ 1 chỉ số.\n'
  + '- Thiếu dữ liệu chỉ số nào thì ghi rõ "thiếu dữ liệu", TUYỆT ĐỐI KHÔNG bịa số.\n'
  + '- ĐÂY LÀ ĐÁNH GIÁ ĐỊNH GIÁ THAM KHẢO, KHÔNG phải khuyến nghị mua/bán. Nhắc người dùng kiểm chứng thêm bằng báo cáo tài chính gốc.\n'
  + '- Bố cục: (1) 💎 Xếp hạng RẺ → ĐẮT, (2) 🔎 Phân tích sâu BID/BCM/FPT, (3) ⚠️ Bẫy định giá cần lưu ý.\n'
  + '- Markdown đơn giản, dễ đọc điện thoại, tối đa ~550 từ.';

const userContent = 'Ngày ' + today + '. Chỉ số cơ bản mới nhất (nguồn VNDirect; ROE/ROA/Biên LN/Cổ tức đơn vị %; "n/a" = chưa lấy được):\n\n'
  + (table || '(không lấy được dữ liệu)')
  + '\n\nHãy viết báo cáo định giá theo đúng bố cục. Mã nào thiếu chỉ số quan trọng (P/E hoặc P/B) thì nói rõ chưa đủ cơ sở định giá.';

const requestBody = { model: 'claude-opus-4-8', max_tokens: 4000, system, messages: [{ role: 'user', content: userContent }] };

return [{ json: { requestBody, debug } }];

const res = $input.first().json;
let text = '';
if (res && Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!text) {
  if (res && res.type === 'error' && res.error) text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error));
  else if (res && res.stop_reason === 'refusal') text = '⚠️ Bị từ chối bởi bộ lọc an toàn.';
  else text = '⚠️ Không tạo được báo cáo (phản hồi rỗng).';
}
const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const full = '💎 *ĐỊNH GIÁ CƠ BẢN (Lớp 4)*\n_' + now + '_\n\n' + text + '\n\n_Chỉ số: VNDirect · Phân tích: Claude AI · ảnh chụp hiện tại so ngưỡng ngành, chưa so dải lịch sử · KHÔNG phải khuyến nghị đầu tư_';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) { let cut = s.lastIndexOf('\n', SIZE); if (cut < SIZE * 0.5) cut = SIZE; parts.push(s.slice(0, cut)); s = s.slice(cut); }
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
